"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["83282"],{95097(e,t,n){n.d(t,{Ay:()=>h,RM:()=>i});var a=n(74848),o=n(28453),s=n(66422);let i=[];function r(e){let t={admonition:"admonition",blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"teaching-you-to-trade-stocks-1-an-economic-man-who-cant-make-money-is-nothing-but-a-waste",children:"Teaching You to Trade Stocks 1: An Economic Man Who Can't Make Money Is Nothing but a Waste!"})}),"\n",(0,a.jsxs)(t.blockquote,{children:["\n",(0,a.jsx)(t.p,{children:"2006/6/7 18:08:15"}),"\n"]}),"\n",(0,a.jsx)(t.admonition,{title:"Reader-contributed image, verify independently",type:"warning",children:(0,a.jsx)("div",{style:{textAlign:"left"},children:(0,a.jsx)("img",{src:(0,s.Ay)("/img/stocks/001/1.png"),style:{marginTop:"15px",width:1e3}})})}),"\n",(0,a.jsx)(t.p,{children:'A topic like "Teaching You to Trade Stocks" \u2014 there isn\'t a second person in all of China more suited to write this than this ID. Of course, stocks are traded, not written about, so I never thought of writing on such a topic. But everything has its karmic origin, and when the time comes, why not write a bit.'}),"\n",(0,a.jsx)(t.p,{children:"People are always quite strange. Even very smart people, or those highly successful in other industries, the moment they enter the capital markets, it's like they become different people. The chasm between the virtual and the real means that those running real businesses \u2014 never mind futures \u2014 even in the comparatively less risky stock market, rarely do well. And those accustomed to playing games in virtual markets can hardly ever turn back to real industry. There are far too many such examples."}),"\n",(0,a.jsx)(t.p,{children:"Among friends around me involved in economics, those in finance are the majority, with a few in real industry. Last year after the RMB was liberalized, we were hanging out together and the conversation happened to turn to stocks. My opinion at the time was that due to the global uptrend in resources and RMB appreciation, domestic industry would face great difficulties, while the virtual market, due to its capital absorption effect, would see significant improvement \u2014 there would be a rally of at least a major X-wave level \u2014 and I advised them to divert some funds into the capital markets. Because in the previous few years, people kept getting burned one after another in the capital markets, these guys were very hesitant, and before they knew it, the window had passed."}),"\n",(0,a.jsx)(t.p,{children:"This year, after the Spring Festival, these guys suddenly started pestering this ID nonstop, saying they wanted to enter the market. By then this ID was already too busy to spare any attention, so I gave them a good scolding and told them: right now even a dog could make money, go play on your own, I don't have time for you."}),"\n",(0,a.jsx)(t.p,{children:"Entering March and April, by then the non-ferrous metals and other sectors were already blazing hot. These guys wanted to go big but feared the risk, and had been just dabbling in small amounts. One day, we were hanging out again and they insisted this ID pick some specific stocks. Because over these two years, many large foreign funds had been coming in to acquire Chinese fast-moving consumer goods companies, and some large cyclical industries were facing restructuring, I told them to focus on these two types of stocks plus warrants."}),"\n",(0,a.jsx)(t.p,{children:"After May, the stock market surged and everyone was busy. When we had the chance to meet again in the middle of the month, I asked around and found that basically none of them had bought much, and those who did had gotten off after just a few stops. They all seemed very agitated, constantly asking what they could buy. Feeling both a bit sorry for them and a bit annoyed \u2014 how is it that people who do perfectly fine outside the market all become like this once they're in it? I somewhat dismissively told them to buy local stocks priced around 3 yuan in both Shenzhen and Shanghai, and warned them that continuing like this would definitely lead to problems. They'd better learn properly on their own \u2014 no matter how skilled someone else is, they can't babysit you like a child every day."}),"\n",(0,a.jsx)(t.admonition,{title:"Reader-contributed image, verify independently",type:"warning",children:(0,a.jsx)("div",{style:{textAlign:"left"},children:(0,a.jsx)("img",{src:(0,s.Ay)("/img/stocks/001/2.png"),style:{marginTop:"15px",width:1e3}})})}),"\n",(0,a.jsx)(t.p,{children:"Last Sunday, we met again. These fellows, probably all loaded up on stocks by now, were beaming with excitement this time. Having probably flipped through a few books, listened to some stock commentators, and read some magazines, they were now spouting jargon left and right \u2014 first-tier this, second-tier that \u2014 acting like experts. 1,800, 2,000, 2,500 points \u2014 real big shots now. This market really does transform people! It's just that the market's meat grinder now has fresh material."}),"\n",(0,a.jsx)(t.p,{children:"Some say the market is where veterans make money off newcomers, yet among market veterans, those who've been trapped for 10 or 8 years are a dime a dozen. In truth, the market has always been where the clear-headed make money off the confused. In a market economy, as long as you participate in the economy, you are an economic man, and an economic man's purpose is naturally to make money \u2014 especially in the capital markets. There are no philanthropists here, only winners and losers. And an economic man who can't make money is nothing but a waste! No matter how successful you are in other areas, once you're in the market, winning or losing is the only standard. Everything else is just noise."}),"\n",(0,a.jsx)(t.p,{children:"(To be continued)"})]})}function h(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(r,{...e})}):r(e)}},74540(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>u,frontMatter:()=>r,contentTitle:()=>h,toc:()=>d,assets:()=>l});var a=JSON.parse('{"id":"stocks/001","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/stocks/001.md","sourceDirName":"stocks","slug":"/stocks/001","permalink":"/en/stocks/001","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"001","title":"","hide_table_of_contents":true,"sidebar_label":"Teaching You Stock Trading 1: An Economic Man Who Can\'t Make Money Is Just a Waste! (2006/6/7 18:08:15)"},"sidebar":"stocksExtendedSidebar","previous":{"title":"Changhong: From Big Boss to Grandson for Just 300 Million Dollars! (2006/6/6 21:09:45)","permalink":"/en/stocks/changhong"},"next":{"title":"Teaching You Stock Trading 2: There Are No Market Makers \u2014 Only Winners and Losers! (2006/6/7 22:41:27)","permalink":"/en/stocks/002"}}'),o=n(74848),s=n(28453),i=n(95097);let r={id:"001",title:"",hide_table_of_contents:!0,sidebar_label:"Teaching You Stock Trading 1: An Economic Man Who Can't Make Money Is Just a Waste! (2006/6/7 18:08:15)"},h,l={},d=[...i.RM];function c(e){return(0,o.jsx)(i.Ay,{})}function u(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(c,{...e})}):c(e)}},28453(e,t,n){n.d(t,{R:()=>i,x:()=>r});var a=n(96540);let o={},s=a.createContext(o);function i(e){let t=a.useContext(s);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),a.createElement(s.Provider,{value:t},e.children)}}}]);